#!/bin/sh
# Every component's CRDs (system/crds, generated by scripts/vendor-crds, each annotated Prune=false), applied
# server-side as Argo CD's field manager: by the bootstrap before Argo CD's ApplicationSets, and by just dev and just
# testbed on a running cluster before they push a commit. A component whose chart stops rendering a CRD would otherwise
# have Argo CD prune it, and every object of its kind with it, before the bootstrap ran.
# Usage: apply-crds.sh <repository root>. Env: KUBECONFIG.
set -eu
helm template crds "$1/system/crds" |
	kubectl apply --server-side --field-manager argocd-controller --force-conflicts -f - >/dev/null
